"use strict";

const fs = require("fs");
const fsp = require("fs/promises");

module.exports = async function watcherProbe(fileName) {
  await fsp.mkdir("realnpm-watch", { recursive: true });
  const watchPath = "realnpm-watch/" + fileName;
  await fsp.writeFile(watchPath, "before", "utf8");
  return new Promise((resolve) => {
    let settled = false;
    let timer;
    const watcher = fs.watch(watchPath, { persistent: true }, (eventType) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      watcher.close();
      fsp.rm("realnpm-watch", { recursive: true, force: true }).catch(() => {}).finally(() => {
        const normalized = eventType === "change" || eventType === "rename" ? eventType : "event";
        resolve({ ok: true, summary: "fswatch:" + normalized + "/closed" });
      });
    });
    timer = setTimeout(() => {
      if (settled) {
        return;
      }
      settled = true;
      watcher.close();
      fsp.rm("realnpm-watch", { recursive: true, force: true }).catch(() => {}).finally(() => {
        resolve({ ok: true, summary: "fswatch:timeout-fallback/closed" });
      });
    }, 2500);
    setTimeout(() => {
      try {
        fs.writeFileSync(watchPath, "after", "utf8");
      } catch (error) {
        clearTimeout(timer);
        if (!settled) {
          settled = true;
          watcher.close();
          resolve({
            ok: false,
            summary: "fswatch:write-error/" + String(error && error.code || "unknown") + "/closed",
          });
        }
      }
    }, 120);
  });
};
